REPLACE INTO `battlemon_items` (`id`, `internal_name`, `name`, `name_plural`, `pocket`, `price`, `field_use`, `battle_use`, `flags`, `heal_amount`, `description`) VALUES
(1, 'REPEL', 'Repel', 'Repels', 1, 400, 'Direct', NULL, 'Repel,Fling_30', NULL, 'An item that prevents weak wild Pokémon from appearing for 100 steps after its use.'),
(2, 'SUPERREPEL', 'Super Repel', 'Super Repels', 1, 700, 'Direct', NULL, 'Repel,Fling_30', NULL, 'An item that prevents weak wild Pokémon from appearing for 200 steps after its use.'),
(3, 'MAXREPEL', 'Max Repel', 'Max Repels', 1, 900, 'Direct', NULL, 'Repel,Fling_30', NULL, 'An item that prevents weak wild Pokémon from appearing for 250 steps after its use.'),
(4, 'BLACKFLUTE', 'Black Flute', 'Black Flutes', 1, 20, 'Direct', NULL, 'Fling_30', NULL, 'A black flute made from blown glass. Its melody makes wild Pokémon less likely to appear.'),
(5, 'WHITEFLUTE', 'White Flute', 'White Flutes', 1, 20, 'Direct', NULL, 'Fling_30', NULL, 'A white flute made from blown glass. Its melody makes wild Pokémon more likely to appear.'),
(6, 'HONEY', 'Honey', 'Honey', 1, 900, 'Direct', NULL, 'Fling_30', NULL, 'A sweet honey with a lush aroma that attracts wild Pokémon when used in tall grass, in caves, or elsewhere.'),
(7, 'REDSHARD', 'Red Shard', 'Red Shards', 1, 1000, NULL, NULL, 'Fling_30', NULL, 'A small red shard. It appears to be from some sort of implement made long ago.'),
(8, 'YELLOWSHARD', 'Yellow Shard', 'Yellow Shards', 1, 1000, NULL, NULL, 'Fling_30', NULL, 'A small yellow shard. It appears to be from some sort of implement made long ago.'),
(9, 'BLUESHARD', 'Blue Shard', 'Blue Shards', 1, 1000, NULL, NULL, 'Fling_30', NULL, 'A small blue shard. It appears to be from some sort of implement made long ago.'),
(10, 'GREENSHARD', 'Green Shard', 'Green Shards', 1, 1000, NULL, NULL, 'Fling_30', NULL, 'A small green shard. It appears to be from some sort of implement made long ago.'),
(11, 'FIRESTONE', 'Fire Stone', 'Fire Stones', 1, 3000, 'OnPokemon', NULL, 'EvolutionStone,Fling_30', NULL, 'A peculiar stone that makes certain species of Pokémon evolve. It is colored orange.'),
(12, 'THUNDERSTONE', 'Thunder Stone', 'Thunder Stones', 1, 3000, 'OnPokemon', NULL, 'EvolutionStone,Fling_30', NULL, 'A peculiar stone that makes certain species of Pokémon evolve. It has a thunderbolt pattern.'),
(13, 'WATERSTONE', 'Water Stone', 'Water Stones', 1, 3000, 'OnPokemon', NULL, 'EvolutionStone,Fling_30', NULL, 'A peculiar stone that makes certain species of Pokémon evolve. It is a clear, light blue.'),
(14, 'LEAFSTONE', 'Leaf Stone', 'Leaf Stones', 1, 3000, 'OnPokemon', NULL, 'EvolutionStone,Fling_30', NULL, 'A peculiar stone that makes certain species of Pokémon evolve. It has a leaf pattern.'),
(15, 'MOONSTONE', 'Moon Stone', 'Moon Stones', 1, 3000, 'OnPokemon', NULL, 'EvolutionStone,Fling_30', NULL, 'A peculiar stone that makes certain species of Pokémon evolve. It is as black as the night sky.'),
(16, 'SUNSTONE', 'Sun Stone', 'Sun Stones', 1, 3000, 'OnPokemon', NULL, 'EvolutionStone,Fling_30', NULL, 'A peculiar stone that makes certain species of Pokémon evolve. It is as red as the sun.'),
(17, 'DUSKSTONE', 'Dusk Stone', 'Dusk Stones', 1, 3000, 'OnPokemon', NULL, 'EvolutionStone,Fling_80', NULL, 'A peculiar stone that makes certain species of Pokémon evolve. It is as dark as dark can be.'),
(18, 'DAWNSTONE', 'Dawn Stone', 'Dawn Stones', 1, 3000, 'OnPokemon', NULL, 'EvolutionStone,Fling_80', NULL, 'A peculiar stone that makes certain species of Pokémon evolve. It sparkles like eyes.'),
(19, 'SHINYSTONE', 'Shiny Stone', 'Shiny Stones', 1, 3000, 'OnPokemon', NULL, 'EvolutionStone,Fling_80', NULL, 'A peculiar stone that makes certain species of Pokémon evolve. It shines with a dazzling light.'),
(20, 'ICESTONE', 'Ice Stone', 'Ice Stones', 1, 3000, 'OnPokemon', NULL, 'EvolutionStone,Fling_30', NULL, 'A peculiar stone that makes certain species of Pokémon evolve. It has a snowflake pattern.'),
(21, 'SWEETAPPLE', 'Sweet Apple', 'Sweet Apples', 1, 2200, 'OnPokemon', NULL, 'EvolutionStone,Fling_30', NULL, 'A peculiar apple that can make a certain species of Pokémon evolve. It''s exceptionally sweet.'),
(22, 'TARTAPPLE', 'Tart Apple', 'Tart Apples', 1, 2200, 'OnPokemon', NULL, 'EvolutionStone,Fling_30', NULL, 'A peculiar apple that can make a certain species of Pokémon evolve. It''s exceptionally tart.'),
(23, 'CRACKEDPOT', 'Cracked Pot', 'Cracked Pots', 1, 3000, 'OnPokemon', NULL, 'EvolutionStone,Fling_80', NULL, 'A peculiar cracked teapot that can make a certain species of Pokémon evolve. It makes delicious tea.'),
(24, 'CHIPPEDPOT', 'Chipped Pot', 'Chipped Pots', 1, 3000, 'OnPokemon', NULL, 'EvolutionStone,Fling_80', NULL, 'A peculiar chipped teapot that can make a certain species of Pokémon evolve. It makes delicious tea.'),
(25, 'GALARICACUFF', 'Galarica Cuff', 'Galarica Cuffs', 1, 6000, 'OnPokemon', NULL, 'EvolutionStone,Fling_30', NULL, 'A cuff made from woven-together Galarica Twigs. Giving it to a Galarian Slowpoke would make it very happy.'),
(26, 'GALARICAWREATH', 'Galarica Wreath', 'Galarica Wreaths', 1, 6000, 'OnPokemon', NULL, 'EvolutionStone,Fling_30', NULL, 'A wreath made from woven-together Galarica Twigs. A Galarian Slowpoke wearing this would be very happy.'),
(27, 'REDAPRICORN', 'Red Apricorn', 'Red Apricorns', 1, 200, NULL, NULL, 'Apricorn', NULL, 'A red Apricorn. It assails your nostrils.'),
(28, 'YELLOWAPRICORN', 'Yellow Apricorn', 'Yellow Apricorns', 1, 200, NULL, NULL, 'Apricorn', NULL, 'A yellow Apricorn. It has an invigorating scent.'),
(29, 'BLUEAPRICORN', 'Blue Apricorn', 'Blue Apricorns', 1, 200, NULL, NULL, 'Apricorn', NULL, 'A blue Apricorn. It smells a bit like grass.'),
(30, 'GREENAPRICORN', 'Green Apricorn', 'Green Apricorns', 1, 200, NULL, NULL, 'Apricorn', NULL, 'A green Apricorn. It has a mysterious, aromatic scent.'),
(31, 'PINKAPRICORN', 'Pink Apricorn', 'Pink Apricorns', 1, 200, NULL, NULL, 'Apricorn', NULL, 'A pink Apricorn. It has a nice, sweet scent.'),
(32, 'WHITEAPRICORN', 'White Apricorn', 'White Apricorns', 1, 200, NULL, NULL, 'Apricorn', NULL, 'A white Apricorn. It doesn''t smell like anything.'),
(33, 'BLACKAPRICORN', 'Black Apricorn', 'Black Apricorns', 1, 200, NULL, NULL, 'Apricorn', NULL, 'A black Apricorn. It has an indescribable scent.'),
(34, 'HELIXFOSSIL', 'Helix Fossil', 'Helix Fossils', 1, 7000, NULL, NULL, 'Fossil,Fling_100', NULL, 'A fossil of an ancient Pokémon that lived in the sea. It appears to be part of a seashell.'),
(35, 'DOMEFOSSIL', 'Dome Fossil', 'Dome Fossils', 1, 7000, NULL, NULL, 'Fossil,Fling_100', NULL, 'A fossil of an ancient Pokémon that lived in the sea. It appears to be part of a shell.'),
(36, 'OLDAMBER', 'Old Amber', 'Old Ambers', 1, 1000, NULL, NULL, 'Fossil,Fling_100', NULL, 'A piece of amber that contains the genes of an ancient Pokémon. It is clear with a reddish tint.'),
(37, 'ROOTFOSSIL', 'Root Fossil', 'Root Fossils', 1, 7000, NULL, NULL, 'Fossil,Fling_100', NULL, 'A fossil of an ancient Pokémon that lived in the sea. It appears to be part of a plant root.'),
(38, 'CLAWFOSSIL', 'Claw Fossil', 'Claw Fossils', 1, 7000, NULL, NULL, 'Fossil,Fling_100', NULL, 'A fossil of an ancient Pokémon that lived in the sea. It appears to be part of a claw.'),
(39, 'SKULLFOSSIL', 'Skull Fossil', 'Skull Fossils', 1, 7000, NULL, NULL, 'Fossil,Fling_100', NULL, 'A fossil from a prehistoric Pokémon that lived on the land. It appears to be part of a head.'),
(40, 'ARMORFOSSIL', 'Armor Fossil', 'Armor Fossils', 1, 7000, NULL, NULL, 'Fossil,Fling_100', NULL, 'A fossil from a prehistoric Pokémon that lived on the land. It appears to be part of a collar.'),
