(43, 'JAWFOSSIL', 'Jaw Fossil', 'Jaw Fossils', 1, 7000, NULL, NULL, 'Fossil,Fling_100', NULL, 'A fossil from a prehistoric Pokémon that once lived on the land. It appears to be part of a large jaw.'),
(44, 'SAILFOSSIL', 'Sail Fossil', 'Sail Fossils', 1, 7000, NULL, NULL, 'Fossil,Fling_100', NULL, 'A fossil from a prehistoric Pokémon that once lived on the land. It looks like the impression from a skin sail.'),
(45, 'FOSSILIZEDBIRD', 'Fossilized Bird', 'Fossilized Birds', 1, 5000, NULL, NULL, 'Fling_100', NULL, 'The fossil of an ancient Pokémon that once soared through the sky. What it looked like is a mystery.'),
(46, 'FOSSILIZEDFISH', 'Fossilized Fish', 'Fossilized Fish', 1, 5000, NULL, NULL, 'Fling_100', NULL, 'The fossil of an ancient Pokémon that once lived in the sea. What it looked like is a mystery.'),
(47, 'FOSSILIZEDDRAKE', 'Fossilized Drake', 'Fossilized Drakes', 1, 5000, NULL, NULL, 'Fling_100', NULL, 'The fossil of an ancient Pokémon that once roamed the land. What it looked like is a mystery.'),
(48, 'FOSSILIZEDDINO', 'Fossilized Dino', 'Fossilized Dinos', 1, 5000, NULL, NULL, 'Fling_100', NULL, 'The fossil of an ancient Pokémon that once lived in the sea. What it looked like is a mystery.'),
(49, 'PRETTYFEATHER', 'Pretty Feather', 'Pretty Feathers', 1, 1000, NULL, NULL, 'Fling_20', NULL, 'Though this feather is beautiful, it''s just a regular feather and has no effect on Pokémon.'),
(50, 'TINYMUSHROOM', 'Tiny Mushroom', 'Tiny Mushrooms', 1, 500, NULL, NULL, 'Fling_30', NULL, 'A small and rare mushroom. It is sought after by collectors.'),
(51, 'BIGMUSHROOM', 'Big Mushroom', 'Big Mushrooms', 1, 5000, NULL, NULL, 'Fling_30', NULL, 'A large and rare mushroom. It is sought after by collectors.'),
(52, 'BALMMUSHROOM', 'Balm Mushroom', 'Balm Mushrooms', 1, 15000, NULL, NULL, 'Fling_30', NULL, 'A rare mushroom which gives off a nice fragrance. A maniac will buy it for a high price.'),
(53, 'PEARL', 'Pearl', 'Pearls', 1, 2000, NULL, NULL, 'Fling_30', NULL, 'A somewhat-small pearl that sparkles in a pretty silver color. It can be sold cheaply to shops.'),
(54, 'BIGPEARL', 'Big Pearl', 'Big Pearls', 1, 8000, NULL, NULL, 'Fling_30', NULL, 'A quite-large pearl that sparkles in a pretty silver color. It can be sold at a high price to shops.'),
(55, 'PEARLSTRING', 'Pearl String', 'Pearl Strings', 1, 20000, NULL, NULL, 'Fling_30', NULL, 'Very large pearls that sparkle in a pretty silver color. A maniac will buy them for a high price.'),
(56, 'STARDUST', 'Stardust', 'Stardusts', 1, 3000, NULL, NULL, 'Fling_30', NULL, 'Lovely, red-colored sand with a loose, silky feel. It can be sold at a high price to shops.'),
(57, 'STARPIECE', 'Star Piece', 'Star Pieces', 1, 12000, NULL, NULL, 'Fling_30', NULL, 'A shard of a pretty gem that sparkles in a red color. It can be sold at a high price to shops.'),
(58, 'COMETSHARD', 'Comet Shard', 'Comet Shards', 1, 25000, NULL, NULL, 'Fling_30', NULL, 'A shard which fell to the ground when a comet approached. A maniac will buy it for a high price.'),
(59, 'NUGGET', 'Nugget', 'Nuggets', 1, 10000, NULL, NULL, 'Fling_30', NULL, 'A nugget of pure gold that gives off a lustrous gleam. It can be sold at a high price to shops.'),
