(61, 'HEARTSCALE', 'Heart Scale', 'Heart Scales', 1, 100, NULL, NULL, 'Fling_30', NULL, 'A pretty, heart-shaped scale that is extremely rare. It glows faintly in the colors of the rainbow.'),
