(63, 'RAREBONE', 'Rare Bone', 'Rare Bones', 1, 5000, NULL, NULL, 'Fling_100', NULL, 'A bone that is extremely valuable for Pokémon archaeology. It can be sold for a high price to shops.'),
(64, 'RELICCOPPER', 'Relic Copper', 'Relic Coppers', 1, 0, NULL, NULL, 'Fling_30', NULL, 'A copper coin used in a civilization about 3,000 years ago. A maniac will buy it for a high price.'),
(65, 'RELICSILVER', 'Relic Silver', 'Relic Silvers', 1, 0, NULL, NULL, 'Fling_30', NULL, 'A silver coin used in a civilization about 3,000 years ago. A maniac will buy it for a high price.'),
