(67, 'RELICVASE', 'Relic Vase', 'Relic Vases', 1, 0, NULL, NULL, 'Fling_30', NULL, 'A vase made in a civilization about 3,000 years ago. A maniac will buy it for a high price.'),
(68, 'RELICBAND', 'Relic Band', 'Relic Bands', 1, 0, NULL, NULL, 'Fling_30', NULL, 'A bracelet made in a civilization about 3,000 years ago. A maniac will buy it for a high price.'),
