(71, 'GROWTHMULCH', 'Growth Mulch', 'Growth Mulch', 1, 200, NULL, NULL, 'Mulch,Fling_30', NULL, 'A fertilizer to be spread on soft soil in regions where Berries are grown. A maniac will buy it for a high price.'),
(72, 'DAMPMULCH', 'Damp Mulch', 'Damp Mulch', 1, 200, NULL, NULL, 'Mulch,Fling_30', NULL, 'A fertilizer to be spread on soft soil in regions where Berries are grown. A maniac will buy it for a high price.'),
(73, 'STABLEMULCH', 'Stable Mulch', 'Stable Mulch', 1, 200, NULL, NULL, 'Mulch,Fling_30', NULL, 'A fertilizer to be spread on soft soil in regions where Berries are grown. A maniac will buy it for a high price.'),
(74, 'GOOEYMULCH', 'Gooey Mulch', 'Gooey Mulch', 1, 200, NULL, NULL, 'Mulch,Fling_30', NULL, 'A fertilizer to be spread on soft soil in regions where Berries are grown. A maniac will buy it for a high price.'),
(75, 'SHOALSALT', 'Shoal Salt', 'Shoal Salts', 1, 20, NULL, NULL, 'Fling_30', NULL, 'Pure salt that can be discovered deep inside the Shoal Cave. A maniac will buy it for a high price.'),
