(77, 'ODDKEYSTONE', 'Odd Keystone', 'Odd Keystones', 1, 2100, NULL, NULL, 'Fling_80', NULL, 'A vital item that is needed to keep a stone tower from collapsing. Voices can be heard from it occasionally.'),
(78, 'REDNECTAR', 'Red Nectar', 'Red Nectars', 1, 300, 'OnPokemon', NULL, 'Fling_10', NULL, 'A flower nectar obtained at Ula''ula Meadow. It changes the form of certain species of Pokémon.'),
