(80, 'PINKNECTAR', 'Pink Nectar', 'Pink Nectars', 1, 300, 'OnPokemon', NULL, 'Fling_10', NULL, 'A flower nectar obtained from shrubs on Royal Avenue. It changes the form of certain species of Pokémon.');
REPLACE INTO `battlemon_items` (`id`, `internal_name`, `name`, `name_plural`, `pocket`, `price`, `field_use`, `battle_use`, `flags`, `heal_amount`, `description`) VALUES
(81, 'PURPLENECTAR', 'Purple Nectar', 'Purple Nectars', 1, 300, 'OnPokemon', NULL, 'Fling_10', NULL, 'A flower nectar obtained at Poni Meadow. It changes the form of certain species of Pokémon.'),
(82, 'AIRBALLOON', 'Air Balloon', 'Air Balloons', 1, 3000, NULL, NULL, 'Fling_10', NULL, 'An item to be held by a Pokémon. The holder will float in the air until hit. Once hit, this item will burst.'),
(83, 'BRIGHTPOWDER', 'Bright Powder', 'Bright Powders', 1, 3000, NULL, NULL, 'Fling_10', NULL, 'An item to be held by a Pokémon. It casts a tricky glare that lowers the opponent''s accuracy.'),
(84, 'EVIOLITE', 'Eviolite', 'Eviolites', 1, 3000, NULL, NULL, 'Fling_40', NULL, 'A mysterious evolutionary lump. When held, it raises the Defense and Sp. Def if the holder can still evolve.'),
(85, 'FLOATSTONE', 'Float Stone', 'Float Stones', 1, 3000, NULL, NULL, 'Fling_30', NULL, 'A very light stone. It reduces the weight of a Pokémon when held.'),
(86, 'DESTINYKNOT', 'Destiny Knot', 'Destiny Knots', 1, 3000, NULL, NULL, 'Fling_10', NULL, 'A long, thin, bright-red string to be held by a Pokémon. If the holder becomes infatuated, so does the foe.'),
(87, 'ROCKYHELMET', 'Rocky Helmet', 'Rocky Helmets', 1, 3000, NULL, NULL, 'Fling_60', NULL, 'If the holder of this item takes damage, the attacker will also be damaged upon contact.'),
(88, 'ASSAULTVEST', 'Assault Vest', 'Assault Vests', 1, 1000, NULL, NULL, 'Fling_80', NULL, 'An item to be held by a Pokémon. This offensive vest raises Sp. Def but prevents the use of status moves.'),
(89, 'SAFETYGOGGLES', 'Safety Goggles', 'Safety Goggles', 1, 3000, NULL, NULL, 'Fling_80', NULL, 'An item to be held by a Pokémon. They protect the holder from weather-related damage and powder.'),
(90, 'PROTECTIVEPADS', 'Protective Pads', 'Protective Pads', 1, 3000, NULL, NULL, 'Fling_30', NULL, 'An item to be held by a Pokémon. They protect the holder from effects caused by making contact.'),
(91, 'HEAVYDUTYBOOTS', 'Heavy-Duty Boots', 'Heavy-Duty Boots', 1, 3000, NULL, NULL, 'Fling_80', NULL, 'These boots prevent the effects of traps set on the battlefield.'),
(92, 'UTILITYUMBRELLA', 'Utility Umbrella', 'Utility Umbrellas', 1, 3000, NULL, NULL, 'Fling_60', NULL, 'An item to be held by a Pokémon. This sturdy umbrella protects the holder from the effects of rain and sun.'),
(93, 'EJECTBUTTON', 'Eject Button', 'Eject Buttons', 1, 3000, NULL, NULL, 'Fling_30', NULL, 'If the holder is hit by an attack, it will switch with another Pokémon in your party.'),
(94, 'EJECTPACK', 'Eject Pack', 'Eject Packs', 1, 3000, NULL, NULL, 'Fling_50', NULL, 'An item to be held by a Pokémon. When the holder''s stats are lowered, it will be switched out of battle.'),
(95, 'REDCARD', 'Red Card', 'Red Cards', 1, 3000, NULL, NULL, 'Fling_10', NULL, 'A card with a mysterious power. When the holder is struck by a foe, the attacker is removed from battle.'),
(96, 'SHEDSHELL', 'Shed Shell', 'Shed Shells', 1, 3000, NULL, NULL, 'Fling_10', NULL, 'An item to be held by a Pokémon. This discarded carapace lets the holder switch out of battle without fail.'),
(97, 'SMOKEBALL', 'Smoke Ball', 'Smoke Balls', 1, 3000, NULL, NULL, 'Fling_30', NULL, 'An item to be held by a Pokémon. It enables the holder to flee from any wild Pokémon without fail.'),
(98, 'LUCKYEGG', 'Lucky Egg', 'Lucky Eggs', 1, 10000, NULL, NULL, 'Fling_30', NULL, 'An item to be held by a Pokémon. It is an egg filled with happiness that earns extra Exp. Points in battle.'),
(99, 'EXPSHARE', 'Exp. Share', 'Exp. Shares', 1, 3000, NULL, NULL, 'Fling_30', NULL, 'An item to be held by a Pokémon. The holder gets a share of a battle''s Exp. Points without battling.'),
(100, 'AMULETCOIN', 'Amulet Coin', 'Amulet Coins', 1, 10000, NULL, NULL, 'Fling_30', NULL, 'An item to be held by a Pokémon. It doubles a battle''s prize money if the holding Pokémon joins in.'),
(101, 'SOOTHEBELL', 'Soothe Bell', 'Soothe Bells', 1, 4000, NULL, NULL, 'Fling_10', NULL, 'An item to be held by a Pokémon. The comforting chime of this bell calms the holder, making it friendly.'),
(102, 'CLEANSETAG', 'Cleanse Tag', 'Cleanse Tags', 1, 5000, NULL, NULL, 'Fling_30', NULL, 'An item to be held by a Pokémon. It helps keep wild Pokémon away if the holder is the first one in the party.'),
(103, 'CHOICEBAND', 'Choice Band', 'Choice Bands', 1, 4000, NULL, NULL, 'Fling_10', NULL, 'An item to be held by a Pokémon. This headband ups Attack, but allows the use of only one move.'),
(104, 'CHOICESPECS', 'Choice Specs', 'Choice Specs', 1, 4000, NULL, NULL, 'Fling_10', NULL, 'An item to be held by a Pokémon. These curious glasses boost Sp. Atk but allows the use of only one move.'),
(105, 'CHOICESCARF', 'Choice Scarf', 'Choice Scarves', 1, 4000, NULL, NULL, 'Fling_10', NULL, 'An item to be held by a Pokémon. This scarf boosts Speed but allows the use of only one move.'),
(106, 'HEATROCK', 'Heat Rock', 'Heat Rocks', 1, 4000, NULL, NULL, 'Fling_60', NULL, 'A Pokémon held item that extends the duration of the move Sunny Day used by the holder.'),
(107, 'DAMPROCK', 'Damp Rock', 'Damp Rocks', 1, 4000, NULL, NULL, 'Fling_60', NULL, 'A Pokémon held item that extends the duration of the move Rain Dance used by the holder.'),
(108, 'SMOOTHROCK', 'Smooth Rock', 'Smooth Rocks', 1, 4000, NULL, NULL, 'Fling_10', NULL, 'A Pokémon held item that extends the duration of the move Sandstorm used by the holder.'),
(109, 'ICYROCK', 'Icy Rock', 'Icy Rocks', 1, 4000, NULL, NULL, 'Fling_40', NULL, 'A Pokémon held item that extends the duration of the move Hail used by the holder.'),
(110, 'TERRAINEXTENDER', 'Terrain Extender', 'Terrain Extenders', 1, 4000, NULL, NULL, 'Fling_60', NULL, 'An item to be held by a Pokémon. It extends the duration of the terrain caused by the holder.'),
(111, 'LIGHTCLAY', 'Light Clay', 'Light Clays', 1, 4000, NULL, NULL, 'Fling_30', NULL, 'An item to be held by a Pokémon. Protective moves like Light Screen and Reflect will be effective longer.'),
(112, 'GRIPCLAW', 'Grip Claw', 'Grip Claws', 1, 4000, NULL, NULL, 'Fling_90', NULL, 'A Pokémon held item that extends the duration of multiturn attacks like Bind and Wrap.'),
(113, 'BINDINGBAND', 'Binding Band', 'Binding Bands', 1, 3000, NULL, NULL, 'Fling_30', NULL, 'A band that increases the power of binding moves when held.'),
(114, 'BIGROOT', 'Big Root', 'Big Roots', 1, 4000, NULL, NULL, 'Fling_10', NULL, 'A Pokémon held item that boosts the power of HP-stealing moves to let the holder recover more HP.'),
(115, 'BLACKSLUDGE', 'Black Sludge', 'Black Sludges', 1, 3000, NULL, NULL, 'Fling_30', NULL, 'A held item that gradually restores the HP of Poison-type Pokémon. It inflicts damage on all other types.'),
(116, 'LEFTOVERS', 'Leftovers', 'Leftovers', 1, 4000, NULL, NULL, 'Fling_10', NULL, 'An item to be held by a Pokémon. The holder''s HP is gradually restored during battle.'),
(117, 'SHELLBELL', 'Shell Bell', 'Shell Bells', 1, 4000, NULL, NULL, 'Fling_30', NULL, 'An item to be held by a Pokémon. The holder''s HP is restored a little every time it inflicts damage.'),
(118, 'MENTALHERB', 'Mental Herb', 'Mental Herbs', 1, 4000, NULL, NULL, 'Fling_10', NULL, 'An item to be held by a Pokémon. It snaps the holder out of infatuation. It can be used only once.'),
(119, 'WHITEHERB', 'White Herb', 'White Herbs', 1, 4000, NULL, NULL, 'Fling_10', NULL, 'An item to be held by a Pokémon. It restores any lowered stat in battle. It can be used only once.'),
(120, 'POWERHERB', 'Power Herb', 'Power Herbs', 1, 4000, NULL, NULL, 'Fling_10', NULL, 'A single-use item to be held by a Pokémon. It allows the immediate use of a move that charges up first.'),
(121, 'ABSORBBULB', 'Absorb Bulb', 'Absorb Bulbs', 1, 4000, NULL, NULL, 'Fling_30', NULL, 'A consumable bulb. If the holder is hit by a Water-type move, its Sp. Atk will rise.'),
(122, 'CELLBATTERY', 'Cell Battery', 'Cell Batteries', 1, 4000, NULL, NULL, 'Fling_30', NULL, 'A consumable battery. If the holder is hit by an Electric-type move, its Attack will rise.'),
(123, 'LUMINOUSMOSS', 'Luminous Moss', 'Luminous Moss', 1, 4000, NULL, NULL, 'Fling_30', NULL, 'An item to be held by a Pokémon. It boosts Sp. Def if hit by a Water-type attack. It can only be used once.'),
(124, 'SNOWBALL', 'Snowball', 'Snowballs', 1, 4000, NULL, NULL, 'Fling_30', NULL, 'An item to be held by a Pokémon. It boosts Attack if hit by an Ice-type attack. It can only be used once.'),
