(266, 'OVALSTONE', 'Oval Stone', 'Oval Stones', 1, 3000, NULL, NULL, 'Fling_80', NULL, 'A peculiar stone that makes certain species of Pokémon evolve. It is shaped like an egg.'),
(267, 'WHIPPEDDREAM', 'Whipped Dream', 'Whipped Dreams', 1, 3000, NULL, NULL, 'Fling_80', NULL, 'A soft and sweet treat made of fluffy, puffy and whirled cream. It''s loved by a certain Pokémon.'),
