(321, 'AUDINITE', 'Audinite', 'Audinites', 1, 0, NULL, NULL, 'MegaStone,Fling_80', NULL, 'One of a variety of mysterious Mega Stones. Have Audino hold it, and it will be able to Mega Evolve.'),
(322, 'DIANCITE', 'Diancite', 'Diancites', 1, 0, NULL, NULL, 'MegaStone,Fling_80', NULL, 'One of a variety of mysterious Mega Stones. Have Diancie hold it, and it will be able to Mega Evolve.'),
(323, 'REDORB', 'Red Orb', 'Red Orbs', 1, 10000, NULL, NULL, NULL, NULL, 'A shiny red orb that is said to have a legend tied to it. It''s known to be connected with the Hoenn region.'),
(324, 'BLUEORB', 'Blue Orb', 'Blue Orbs', 1, 10000, NULL, NULL, NULL, NULL, 'A shiny blue orb that is said to have a legend tied to it. It''s known to be connected with the Hoenn region.'),
(325, 'POTION', 'Potion', 'Potions', 2, 200, 'OnPokemon', 'OnPokemon', 'Fling_30', '20', 'A spray-type medicine for treating wounds. It can be used to restore 20 HP to a single Pokémon.'),
(326, 'SUPERPOTION', 'Super Potion', 'Super Potions', 2, 700, 'OnPokemon', 'OnPokemon', 'Fling_30', '60', 'A spray-type medicine for treating wounds. It can be used to restore 60 HP to a single Pokémon.'),
(327, 'HYPERPOTION', 'Hyper Potion', 'Hyper Potions', 2, 1500, 'OnPokemon', 'OnPokemon', 'Fling_30', '120', 'A spray-type medicine for treating wounds. It can be used to restore 120 HP to a single Pokémon.'),
(328, 'MAXPOTION', 'Max Potion', 'Max Potions', 2, 2500, 'OnPokemon', 'OnPokemon', 'Fling_30', 'full', 'A spray-type medicine for treating wounds. It can completely restore the max HP of a single Pokémon.'),
(329, 'FULLRESTORE', 'Full Restore', 'Full Restores', 2, 3000, 'OnPokemon', 'OnPokemon', 'Fling_30', 'full', 'A medicine that fully restores the HP and heals any status problems of a single Pokémon.'),
(330, 'SACREDASH', 'Sacred Ash', 'Sacred Ashes', 2, 50000, 'Direct', NULL, 'Fling_30', 'full', 'It revives all fainted Pokémon. In doing so, it also fully restores their HP.'),
(331, 'AWAKENING', 'Awakening', 'Awakenings', 2, 200, 'OnPokemon', 'OnPokemon', 'Fling_30', NULL, 'A spray-type medicine. It awakens a Pokémon from the clutches of sleep.'),
(332, 'ANTIDOTE', 'Antidote', 'Antidotes', 2, 200, 'OnPokemon', 'OnPokemon', 'Fling_30', NULL, 'A spray-type medicine. It lifts the effect of poison from one Pokémon.'),
(333, 'BURNHEAL', 'Burn Heal', 'Burn Heals', 2, 200, 'OnPokemon', 'OnPokemon', 'Fling_30', NULL, 'A spray-type medicine. It heals a single Pokémon that is suffering from a burn.'),
(334, 'PARALYZEHEAL', 'Paralyze Heal', 'Paralyze Heals', 2, 200, 'OnPokemon', 'OnPokemon', 'Fling_30', NULL, 'A spray-type medicine. It eliminates paralysis from a single Pokémon.'),
(335, 'ICEHEAL', 'Ice Heal', 'Ice Heals', 2, 200, 'OnPokemon', 'OnPokemon', 'Fling_30', NULL, 'A spray-type medicine. It defrosts a Pokémon that has been frozen solid.'),
(336, 'FULLHEAL', 'Full Heal', 'Full Heals', 2, 400, 'OnPokemon', 'OnPokemon', 'Fling_30', NULL, 'A spray-type medicine. It heals all the status problems of a single Pokémon.'),
(337, 'PEWTERCRUNCHIES', 'Pewter Crunchies', 'Pewter Crunchies', 2, 250, 'OnPokemon', 'OnPokemon', 'Fling_30', NULL, 'Pewter City''s famous crunchy snack. They can be used to heal all status conditions of a single Pokémon.'),
(338, 'RAGECANDYBAR', 'Rage Candy Bar', 'Rage Candy Bars', 2, 350, 'OnPokemon', 'OnPokemon', 'Fling_30', NULL, 'Mahogany Town''s famous candy. It can be used once to heal all the status conditions of a Pokémon.'),
(339, 'LAVACOOKIE', 'Lava Cookie', 'Lava Cookies', 2, 350, 'OnPokemon', 'OnPokemon', 'Fling_30', NULL, 'Lavaridge Town''s local specialty. It heals all the status problems of one Pokémon.'),
(340, 'OLDGATEAU', 'Old Gateau', 'Old Gateaux', 2, 350, 'OnPokemon', 'OnPokemon', 'Fling_30', NULL, 'Old Chateau''s hidden specialty. It heals all the status problems of a single Pokémon.'),
(341, 'CASTELIACONE', 'Casteliacone', 'Casteliacones', 2, 350, 'OnPokemon', 'OnPokemon', 'Fling_30', NULL, 'Castelia City''s specialty, soft-serve ice cream. It heals all the status problems of a single Pokémon.'),
(342, 'LUMIOSEGALETTE', 'Lumiose Galette', 'Lumiose Galettes', 2, 350, 'OnPokemon', 'OnPokemon', 'Fling_30', NULL, 'A popular treat in Lumiose City. It can be used once to heal all the status conditions of a Pokémon.'),
(343, 'SHALOURSABLE', 'Shalour Sable', 'Shalour Sables', 2, 350, 'OnPokemon', 'OnPokemon', 'Fling_30', NULL, 'Shalour City''s famous shortbread. It can be used once to heal all the status conditions of a Pokémon.'),
(344, 'BIGMALASADA', 'Big Malasada', 'Big Malasadas', 2, 350, 'OnPokemon', 'OnPokemon', 'Fling_30', NULL, 'The Alola region''s specialty--fried bread. It can be used once to heal all the status conditions of a Pokémon.'),
(345, 'REVIVE', 'Revive', 'Revives', 2, 2000, 'OnPokemon', 'OnPokemon', 'Fling_30', 'half', 'A medicine that revives a fainted Pokémon. It restores half the Pokémon''s maximum HP.'),
(346, 'MAXREVIVE', 'Max Revive', 'Max Revives', 2, 4000, 'OnPokemon', 'OnPokemon', 'Fling_30', 'full', 'A medicine that revives a fainted Pokémon. It fully restores the Pokémon''s HP.'),
(347, 'BERRYJUICE', 'Berry Juice', 'Berry Juices', 2, 100, 'OnPokemon', 'OnPokemon', 'Fling_30', '20', 'A 100% pure juice made of Berries. It restores the HP of one Pokémon by just 20 points.'),
(348, 'SWEETHEART', 'Sweet Heart', 'Sweet Hearts', 2, 3000, 'OnPokemon', 'OnPokemon', 'Fling_30', NULL, 'Very sweet chocolate. It restores the HP of one Pokémon by only 20 points.'),
(349, 'FRESHWATER', 'Fresh Water', 'Fresh Waters', 2, 200, 'OnPokemon', 'OnPokemon', 'Fling_30', '30', 'Water with high mineral content. It can be used to restore 30 HP to a single Pokémon.'),
(350, 'SODAPOP', 'Soda Pop', 'Soda Pops', 2, 300, 'OnPokemon', 'OnPokemon', 'Fling_30', '50', 'A highly carbonated soda drink. It can be used to restore 50 HP to a single Pokémon.'),
(351, 'LEMONADE', 'Lemonade', 'Lemonades', 2, 350, 'OnPokemon', 'OnPokemon', 'Fling_30', '70', 'A very sweet and refreshing drink. It can be used to restore 70 HP to a single Pokémon.'),
(352, 'MOOMOOMILK', 'Moomoo Milk', 'Moomoo Milks', 2, 600, 'OnPokemon', 'OnPokemon', 'Fling_30', '100', 'Milk with a very high nutrition content. It restores the HP of one Pokémon by 100 points.'),
(353, 'ENERGYPOWDER', 'Energy Powder', 'Energy Powders', 2, 500, 'OnPokemon', 'OnPokemon', 'Fling_30', '50', 'A very bitter medicinal powder. It can be used to restore 60 HP to a single Pokémon.'),
(354, 'ENERGYROOT', 'Energy Root', 'Energy Roots', 2, 1200, 'OnPokemon', 'OnPokemon', 'Fling_30', '200', 'An extremely bitter medicinal root. It can be used to restore 120 HP to a single Pokémon.'),
(355, 'HEALPOWDER', 'Heal Powder', 'Heal Powders', 2, 300, 'OnPokemon', 'OnPokemon', 'Fling_30', NULL, 'A very bitter medicine powder. It heals all the status problems of a single Pokémon.'),
(356, 'REVIVALHERB', 'Revival Herb', 'Revival Herbs', 2, 2800, 'OnPokemon', 'OnPokemon', 'Fling_30', 'full', 'A very bitter medicinal herb. It revives a fainted Pokémon, fully restoring its HP.'),
(357, 'MAXHONEY', 'Max Honey', 'Max Honeys', 2, 8000, 'OnPokemon', 'OnPokemon', 'Fling_30', NULL, 'Honey that Dynamax Vespiquen produces. It has the same effect as a Max Revive.'),
(358, 'ETHER', 'Ether', 'Ethers', 2, 1200, 'OnPokemon', 'OnMove', 'Fling_30', NULL, 'It restores the PP of a Pokémon''s selected move by a maximum of 10 points.'),
(359, 'MAXETHER', 'Max Ether', 'Max Ethers', 2, 2000, 'OnPokemon', 'OnMove', 'Fling_30', NULL, 'It fully restores the PP of a single selected move that has been learned by the target Pokémon.'),
(360, 'ELIXIR', 'Elixir', 'Elixirs', 2, 3000, 'OnPokemon', 'OnPokemon', 'Fling_30', NULL, 'It restores the PP of all the moves learned by the targeted Pokémon by 10 points each.'),
(361, 'MAXELIXIR', 'Max Elixir', 'Max Elixirs', 2, 4500, 'OnPokemon', 'OnPokemon', 'Fling_30', NULL, 'It fully restores the PP of all the moves learned by the targeted Pokémon.'),
