REPLACE INTO `battlemon_items` (`id`, `internal_name`, `name`, `name_plural`, `pocket`, `price`, `field_use`, `battle_use`, `flags`, `heal_amount`, `description`) VALUES
(401, 'EXPCANDYM', 'Exp. Candy M', 'Exp. Candy Ms', 2, 1000, 'OnPokemon', NULL, 'Fling_30', NULL, 'A candy packed with energy. When consumed, it will grant a Pokémon a moderate amount of Exp. Points.'),
(402, 'EXPCANDYL', 'Exp. Candy L', 'Exp. Candy Ls', 2, 3000, 'OnPokemon', NULL, 'Fling_30', NULL, 'A candy packed with energy. When consumed, it will grant a Pokémon a large amount of Exp. Points.'),
(403, 'EXPCANDYXL', 'Exp. Candy XL', 'Exp. Candy XLs', 2, 10000, 'OnPokemon', NULL, 'Fling_30', NULL, 'A candy packed with energy. When consumed, it will grant a Pokémon a very large amount of Exp. Points.'),
(404, 'RARECANDY', 'Rare Candy', 'Rare Candies', 2, 10000, 'OnPokemon', NULL, 'Fling_30', NULL, 'A candy that is packed with energy. It raises the level of a single Pokémon by one.'),
(405, 'MASTERBALL', 'Master Ball', 'Master Balls', 3, 0, NULL, 'OnFoe', 'PokeBall', NULL, 'The best Ball with the ultimate level of performance. It will catch any wild Pokémon without fail.'),
(406, 'ULTRABALL', 'Ultra Ball', 'Ultra Balls', 3, 800, NULL, 'OnFoe', 'PokeBall', NULL, 'An ultra-performance Ball that provides a higher Pokémon catch rate than a Great Ball.'),
(407, 'GREATBALL', 'Great Ball', 'Great Balls', 3, 600, NULL, 'OnFoe', 'PokeBall', NULL, 'A good, high-performance Ball that provides a higher Pokémon catch rate than a standard Poké Ball.'),
(408, 'POKEBALL', 'Poké Ball', 'Poké Balls', 3, 200, NULL, 'OnFoe', 'PokeBall', NULL, 'A device for catching wild Pokémon. It is thrown like a ball at the target. It is designed as a capsule system.'),
(409, 'SAFARIBALL', 'Safari Ball', 'Safari Balls', 3, 0, NULL, 'OnFoe', 'PokeBall', NULL, 'A special Poké Ball that is used only in the Safari Zone. It is decorated in a camouflage pattern.'),
(410, 'SPORTBALL', 'Sport Ball', 'Sport Balls', 3, 300, NULL, 'OnFoe', 'PokeBall', NULL, 'A special Poké Ball for the Bug-Catching Contest.'),
(411, 'NETBALL', 'Net Ball', 'Net Balls', 3, 1000, NULL, 'OnFoe', 'PokeBall', NULL, 'A somewhat different Poké Ball that works especially well on Water- and Bug-type Pokémon.'),
(412, 'DIVEBALL', 'Dive Ball', 'Dive Balls', 3, 1000, NULL, 'OnFoe', 'PokeBall', NULL, 'A somewhat different Poké Ball that works especially well on Pokémon that live underwater.'),
(413, 'NESTBALL', 'Nest Ball', 'Nest Balls', 3, 1000, NULL, 'OnFoe', 'PokeBall', NULL, 'A somewhat different Poké Ball that works especially well on weaker Pokémon in the wild.'),
(414, 'REPEATBALL', 'Repeat Ball', 'Repeat Balls', 3, 1000, NULL, 'OnFoe', 'PokeBall', NULL, 'A somewhat different Poké Ball that works especially well on Pokémon species that were previously caught.'),
(415, 'TIMERBALL', 'Timer Ball', 'Timer Balls', 3, 1000, NULL, 'OnFoe', 'PokeBall', NULL, 'A somewhat different Ball that becomes progressively better the more turns there are in a battle.'),
(416, 'LUXURYBALL', 'Luxury Ball', 'Luxury Balls', 3, 3000, NULL, 'OnFoe', 'PokeBall', NULL, 'A comfortable Poké Ball that makes a caught wild Pokémon quickly grow friendly.'),
(417, 'PREMIERBALL', 'Premier Ball', 'Premier Balls', 3, 200, NULL, 'OnFoe', 'PokeBall', NULL, 'A somewhat rare Poké Ball that has been specially made to commemorate an event of some sort.'),
(418, 'DUSKBALL', 'Dusk Ball', 'Dusk Balls', 3, 1000, NULL, 'OnFoe', 'PokeBall', NULL, 'A somewhat different Poké Ball that makes it easier to catch wild Pokémon at night or in dark places like caves.'),
(419, 'HEALBALL', 'Heal Ball', 'Heal Balls', 3, 300, NULL, 'OnFoe', 'PokeBall', NULL, 'A remedial Poké Ball that restores the caught Pokémon''s HP and eliminates any status problem.'),
(420, 'QUICKBALL', 'Quick Ball', 'Quick Balls', 3, 1000, NULL, 'OnFoe', 'PokeBall', NULL, 'A somewhat different Poké Ball that provides a better catch rate if used at the start of a wild encounter.'),
(421, 'CHERISHBALL', 'Cherish Ball', 'Cherish Balls', 3, 0, NULL, 'OnFoe', 'PokeBall', NULL, 'A quite rare Poké Ball that has been specially crafted to commemorate an occasion of some sort.'),
(422, 'FASTBALL', 'Fast Ball', 'Fast Balls', 3, 300, NULL, 'OnFoe', 'PokeBall', NULL, 'A Poké Ball that makes it easier to catch fast Pokémon.'),
(423, 'LEVELBALL', 'Level Ball', 'Level Balls', 3, 300, NULL, 'OnFoe', 'PokeBall', NULL, 'A Poké Ball for catching Pokémon that are a lower level than your own.'),
(424, 'LUREBALL', 'Lure Ball', 'Lure Balls', 3, 300, NULL, 'OnFoe', 'PokeBall', NULL, 'A Poké Ball for catching Pokémon hooked by a Rod when fishing.'),
(425, 'HEAVYBALL', 'Heavy Ball', 'Heavy Balls', 3, 300, NULL, 'OnFoe', 'PokeBall', NULL, 'A Poké Ball for catching very heavy Pokémon.'),
(426, 'LOVEBALL', 'Love Ball', 'Love Balls', 3, 300, NULL, 'OnFoe', 'PokeBall', NULL, 'A Poké Ball for catching Pokémon that are the opposite gender of your Pokémon.'),
(427, 'FRIENDBALL', 'Friend Ball', 'Friend Balls', 3, 300, NULL, 'OnFoe', 'PokeBall', NULL, 'A Poké Ball that makes caught Pokémon more friendly.'),
(428, 'MOONBALL', 'Moon Ball', 'Moon Balls', 3, 300, NULL, 'OnFoe', 'PokeBall', NULL, 'A Poké Ball for catching Pokémon that evolve using the Moon Stone.'),
(429, 'DREAMBALL', 'Dream Ball', 'Dream Balls', 3, 300, NULL, 'OnFoe', 'PokeBall', NULL, 'A somewhat different Poké Ball that makes it easier to catch wild Pokémon while they''re asleep.'),
(430, 'BEASTBALL', 'Beast Ball', 'Beast Balls', 3, 1000, NULL, 'OnFoe', 'PokeBall', NULL, 'A special Poké Ball designed to catch Ultra Beasts. It has a low success rate for catching others.'),
(431, 'TM01', 'TM01', 'TM01s', 4, 3000, 'TR', NULL, 'Fling_150', NULL, 'The user focuses its mind before launching a punch. This move fails if the user is hit before it is used.'),
(432, 'TM02', 'TM02', 'TM02s', 4, 3000, 'TR', NULL, 'Fling_80', NULL, 'The user slashes the target with huge sharp claws.'),
(433, 'TM03', 'TM03', 'TM03s', 4, 3000, 'TR', NULL, 'Fling_60', NULL, 'The user attacks the target with a pulsing blast of water. This may also confuse the target.'),
(434, 'TM04', 'TM04', 'TM04s', 4, 1500, 'TR', NULL, 'Fling_10', NULL, 'The user quietly focuses its mind and calms its spirit to raise its Sp. Atk and Sp. Def stats.'),
(435, 'TM05', 'TM05', 'TM05s', 4, 1000, 'TR', NULL, 'Fling_10', NULL, 'The target is scared off, and a different Pokémon is dragged out. In the wild, this ends the battle.'),
(436, 'TM06', 'TM06', 'TM06s', 4, 3000, 'TR', NULL, 'Fling_10', NULL, 'A move that leaves the target badly poisoned. Its poison damage worsens every turn.'),
(437, 'TM07', 'TM07', 'TM07s', 4, 2000, 'TR', NULL, 'Fling_10', NULL, 'The user summons a hailstorm lasting five turns. It damages all Pokémon except Ice types.'),
(438, 'TM08', 'TM08', 'TM08s', 4, 1500, 'TR', NULL, 'Fling_10', NULL, 'The user tenses its muscles to bulk up its body, raising both its Attack and Defense stats.'),
(439, 'TM09', 'TM09', 'TM09s', 4, 2000, 'TR', NULL, 'Fling_25', NULL, 'The user forcefully shoots seeds at the target two to five times in a row.'),
(440, 'TM10', 'TM10', 'TM10s', 4, 1500, 'TR', NULL, 'Fling_10', NULL, 'The user is roused, and its Attack and Sp. Atk stats increase.'),
(441, 'TM11', 'TM11', 'TM11s', 4, 2000, 'TR', NULL, 'Fling_10', NULL, 'The user intensifies the sun for five turns, powering up Fire-type moves and weakening Water-type moves.'),
(442, 'TM12', 'TM12', 'TM12s', 4, 1500, 'TR', NULL, 'Fling_10', NULL, 'The target is taunted into a rage that allows it to use only attack moves for three turns.'),
(443, 'TM13', 'TM13', 'TM13s', 4, 3000, 'TR', NULL, 'Fling_90', NULL, 'The target is struck with an icy-cold beam of energy. This may also leave the target frozen.'),
(444, 'TM14', 'TM14', 'TM14s', 4, 5500, 'TR', NULL, 'Fling_110', NULL, 'A howling blizzard is summoned to strike opposing Pokémon. This may also leave them frozen.'),
(445, 'TM15', 'TM15', 'TM15s', 4, 7500, 'TR', NULL, 'Fling_150', NULL, 'The target is attacked with a powerful beam. The user can''t move on the next turn.'),
(446, 'TM16', 'TM16', 'TM16s', 4, 2000, 'TR', NULL, 'Fling_10', NULL, 'A wondrous wall of light is put up to reduce damage from special attacks for five turns.'),
(447, 'TM17', 'TM17', 'TM17s', 4, 2000, 'TR', NULL, 'Fling_10', NULL, 'The user protects itself from all attacks. Its chance of failing rises if it is used in succession.'),
(448, 'TM18', 'TM18', 'TM18s', 4, 2000, 'TR', NULL, 'Fling_10', NULL, 'The user summons a heavy rain for five turns, powering up Water-type moves and weakening Fire-type ones.'),
(449, 'TM19', 'TM19', 'TM19s', 4, 3000, 'TR', NULL, 'Fling_75', NULL, 'A nutrient-draining attack. The user''s HP is restored by half the damage taken by the target.'),
(450, 'TM20', 'TM20', 'TM20s', 4, 2000, 'TR', NULL, 'Fling_10', NULL, 'The user creates a protective field that prevents status conditions for five turns.'),
(451, 'TM21', 'TM21', 'TM21s', 4, 3000, 'TR', NULL, 'Fling_80', NULL, 'The user damages opposing Pokémon by emitting a powerful flash.'),
(452, 'TM22', 'TM22', 'TM22s', 4, 3000, 'TR', NULL, 'Fling_120', NULL, 'In this two-turn attack, the user gathers light, then blasts a bundled beam on the next turn.'),
(453, 'TM23', 'TM23', 'TM23s', 4, 3000, 'TR', NULL, 'Fling_100', NULL, 'The target is slammed with a steel-hard tail. This may also lower the target''s Defense stat.'),
(454, 'TM24', 'TM24', 'TM24s', 4, 3000, 'TR', NULL, 'Fling_90', NULL, 'A strong electric blast crashes down on the target. This may also leave the target with paralysis.'),
(455, 'TM25', 'TM25', 'TM25s', 4, 5500, 'TR', NULL, 'Fling_110', NULL, 'A wicked thunderbolt is dropped on the target to inflict damage. This may also leave them with paralysis.'),
(456, 'TM26', 'TM26', 'TM26s', 4, 3000, 'TR', NULL, 'Fling_100', NULL, 'The user sets off an earthquake that strikes every Pokémon around it.'),
(457, 'TM27', 'TM27', 'TM27s', 4, 3000, 'TR', NULL, 'Fling_65', NULL, 'The user makes a swift attack on the target''s legs, which lowers the target''s Speed stat.'),
(458, 'TM28', 'TM28', 'TM28s', 4, 2000, 'TR', NULL, 'Fling_80', NULL, 'The user burrows into the ground, then attacks on the next turn. It can also be used to exit dungeons.'),
(459, 'TM29', 'TM29', 'TM29s', 4, 3000, 'TR', NULL, 'Fling_90', NULL, 'The target is hit by a strong telekinetic force. This may also lower the target''s Sp. Def stat.'),
(460, 'TM30', 'TM30', 'TM30s', 4, 3000, 'TR', NULL, 'Fling_80', NULL, 'The user hurls a shadowy blob at the target. This may also lower the target''s Sp. Def stat.'),
(461, 'TM31', 'TM31', 'TM31s', 4, 3000, 'TR', NULL, 'Fling_75', NULL, 'The user attacks with a swift chop. It can also break barriers, such as Light Screen and Reflect.'),
(462, 'TM32', 'TM32', 'TM32s', 4, 1000, 'TR', NULL, 'Fling_10', NULL, 'By moving rapidly, the user makes illusory copies of itself to raise its evasiveness.'),
(463, 'TM33', 'TM33', 'TM33s', 4, 2000, 'TR', NULL, 'Fling_10', NULL, 'A wondrous wall of light is put up to reduce damage from physical attacks for five turns.'),
(464, 'TM34', 'TM34', 'TM34s', 4, 3000, 'TR', NULL, 'Fling_60', NULL, 'The user strikes the target with a quick jolt of electricity. This attack never misses.'),
(465, 'TM35', 'TM35', 'TM35s', 4, 3000, 'TR', NULL, 'Fling_90', NULL, 'The target is scorched with an intense blast of fire. This may also leave the target with a burn.'),
(466, 'TM36', 'TM36', 'TM36s', 4, 3000, 'TR', NULL, 'Fling_90', NULL, 'Unsanitary sludge is hurled at the target. This may also poison the target.'),
(467, 'TM37', 'TM37', 'TM37s', 4, 2000, 'TR', NULL, 'Fling_10', NULL, 'A five-turn sandstorm is summoned to hurt all combatants except Rock, Ground, and Steel types.'),
(468, 'TM38', 'TM38', 'TM38s', 4, 5500, 'TR', NULL, 'Fling_110', NULL, 'The target is attacked with an intense blast of all-consuming fire. This may also leave them with a burn.'),
(469, 'TM39', 'TM39', 'TM39s', 4, 3000, 'TR', NULL, 'Fling_60', NULL, 'Boulders are hurled at the target. This also lowers the target''s Speed stat by preventing its movement.'),
(470, 'TM40', 'TM40', 'TM40s', 4, 3000, 'TR', NULL, 'Fling_60', NULL, 'The user confounds the target with speed, then slashes. This attack never misses.'),
(471, 'TM41', 'TM41', 'TM41s', 4, 1500, 'TR', NULL, 'Fling_10', NULL, 'The user torments and enrages the target, making it incapable of using the same move twice in a row.'),
(472, 'TM42', 'TM42', 'TM42s', 4, 3000, 'TR', NULL, 'Fling_70', NULL, 'This attack move doubles its power if the user is poisoned, burned, or paralyzed.'),
(473, 'TM43', 'TM43', 'TM43s', 4, 3000, 'TR', NULL, 'Fling_70', NULL, 'After making its attack, the user rushes back to switch places with a party Pokémon in waiting.'),
(474, 'TM44', 'TM44', 'TM44s', 4, 3000, 'TR', NULL, 'Fling_10', NULL, 'The user goes to sleep for two turns. This fully restores the user''s HP and heals any status conditions.'),
(475, 'TM45', 'TM45', 'TM45s', 4, 3000, 'TR', NULL, 'Fling_10', NULL, 'If it is the opposite gender of the user, the target becomes infatuated and less likely to attack.'),
(476, 'TM46', 'TM46', 'TM46s', 4, 2000, 'TR', NULL, 'Fling_60', NULL, 'The user attacks and steals the target''s held item simultaneously.'),
(477, 'TM47', 'TM47', 'TM47s', 4, 3000, 'TR', NULL, 'Fling_70', NULL, 'The target is hit with wings of steel. This may also raise the user''s Defense stat.'),
(478, 'TM48', 'TM48', 'TM48s', 4, 3000, 'TR', NULL, 'Fling_10', NULL, 'The user employs its psychic power to exchange Abilities with the target.'),
(479, 'TM49', 'TM49', 'TM49s', 4, 3000, 'TR', NULL, 'Fling_80', NULL, 'The user shoots boiling hot water at its target. This may also leave the target with a burn.'),
(480, 'TM50', 'TM50', 'TM50s', 4, 5500, 'TR', NULL, 'Fling_130', NULL, 'The user attacks the target at full power. The attack''s recoil harshly lowers the user''s Sp. Atk stat.');
REPLACE INTO `battlemon_items` (`id`, `internal_name`, `name`, `name_plural`, `pocket`, `price`, `field_use`, `battle_use`, `flags`, `heal_amount`, `description`) VALUES
(481, 'TM51', 'TM51', 'TM51s', 4, 2000, 'TR', NULL, 'Fling_10', 'full', 'The user lands and rests its body. This move restores the user''s HP by up to half of its max HP.'),
(482, 'TM52', 'TM52', 'TM52s', 4, 5500, 'TR', NULL, 'Fling_120', NULL, 'The user heightens its mental focus and unleashes its power. This may also lower the target''s Sp. Def stat.'),
(483, 'TM53', 'TM53', 'TM53s', 4, 3000, 'TR', NULL, 'Fling_90', NULL, 'The user draws power from nature and fires it at the target. This may also lower the target''s Sp. Def stat.'),
(484, 'TM54', 'TM54', 'TM54s', 4, 2000, 'TR', NULL, 'Fling_40', NULL, 'A restrained attack that prevents the target from fainting. The target is left with at least 1 HP.'),
(485, 'TM55', 'TM55', 'TM55s', 4, 3000, 'TR', NULL, 'Fling_65', NULL, 'If the target''s HP is half or less, this attack will hit with double the power.'),
(486, 'TM56', 'TM56', 'TM56s', 4, 2000, 'TR', NULL, 'Fling_10', NULL, 'The user flings its held item at the target to attack. This move''s power and effects depend on the item.'),
(487, 'TM57', 'TM57', 'TM57s', 4, 3000, 'TR', NULL, 'Fling_50', NULL, 'The user attacks the target with an electric charge. The user may use any remaining charge to raise its Sp. Atk.'),
(488, 'TM58', 'TM58', 'TM58s', 4, 2000, 'TR', NULL, 'Fling_10', NULL, 'The user endures any attack with at least 1 HP. Its chance of failing rises if it is used in succession.'),
(489, 'TM59', 'TM59', 'TM59s', 4, 3000, 'TR', NULL, 'Fling_85', NULL, 'The target is attacked with a shock wave generated by the user''s gaping mouth.'),
(490, 'TM60', 'TM60', 'TM60s', 4, 3000, 'TR', NULL, 'Fling_75', NULL, 'An energy-draining punch. The user''s HP is restored by half the damage taken by the target.'),
(491, 'TM61', 'TM61', 'TM61s', 4, 2000, 'TR', NULL, 'Fling_10', NULL, 'The user shoots a sinister flame at the target to inflict a burn.'),
(492, 'TM62', 'TM62', 'TM62s', 4, 3000, 'TR', NULL, 'Fling_90', NULL, 'The user generates a damaging sound wave by vibration. This may also lower the target''s Sp. Def stat.'),
(493, 'TM63', 'TM63', 'TM63s', 4, 2000, 'TR', NULL, 'Fling_10', NULL, 'The user stimulates its brain by thinking bad thoughts. This sharply raises the user''s Sp. Atk stat.'),
(494, 'TM64', 'TM64', 'TM64s', 4, 7500, 'TR', NULL, 'Fling_250', NULL, 'The user attacks everything around it by causing a tremendous explosion. The user faints upon using this move.'),
(495, 'TM65', 'TM65', 'TM65s', 4, 3000, 'TR', NULL, 'Fling_70', NULL, 'The user slashes with a sharp claw made from shadows. Critical hits land more easily.'),
(496, 'TM66', 'TM66', 'TM66s', 4, 3000, 'TR', NULL, 'Fling_50', NULL, 'The user stores power, then attacks. If the user moves after the target, this attack''s power will be doubled.'),
(497, 'TM67', 'TM67', 'TM67s', 4, 1000, 'TR', NULL, 'Fling_10', NULL, 'The user recycles a held item that has been used in battle so it can be used again.'),
(498, 'TM68', 'TM68', 'TM68s', 4, 7500, 'TR', NULL, 'Fling_150', NULL, 'The user charges at the target using every bit of its power. The user can''t move on the next turn.'),
(499, 'TM69', 'TM69', 'TM69s', 4, 1500, 'TR', NULL, 'Fling_10', NULL, 'The user polishes its body to reduce drag. This sharply raises the Speed stat.'),
(500, 'TM70', 'TM70', 'TM70s', 4, 1000, 'TR', NULL, 'Fling_10', NULL, 'The user flashes a light that lowers the target''s accuracy. It can also be used to illuminate caves.'),
(501, 'TM71', 'TM71', 'TM71s', 4, 3000, 'TR', NULL, 'Fling_100', NULL, 'The user stabs the target from below with sharpened stones. Critical hits land more easily.'),
(502, 'TM72', 'TM72', 'TM72s', 4, 3000, 'TR', NULL, 'Fling_60', NULL, 'The power of this attack move is doubled if the user has been hurt by the target in the same turn.'),
(503, 'TM73', 'TM73', 'TM73s', 4, 2000, 'TR', NULL, 'Fling_10', NULL, 'The user launches a weak jolt of electricity that paralyzes the target.'),
(504, 'TM74', 'TM74', 'TM74s', 4, 3000, 'TR', NULL, 'Fling_10', NULL, 'The user tackles with a high-speed spin. This move is stronger the slower the user is than the target.'),
(505, 'TM75', 'TM75', 'TM75s', 4, 1500, 'TR', NULL, 'Fling_10', NULL, 'A frenetic dance to uplift the fighting spirit. This sharply raises the user''s Attack stat.'),
(506, 'TM76', 'TM76', 'TM76s', 4, 2000, 'TR', NULL, 'Fling_10', NULL, 'The user lays a trap of levitating stones around the opposing team that hurt Pokémon that switch in.'),
(507, 'TM77', 'TM77', 'TM77s', 4, 1500, 'TR', NULL, 'Fling_10', NULL, 'The user hypnotizes itself into copying any stat change made by the target.'),
(508, 'TM78', 'TM78', 'TM78s', 4, 3000, 'TR', NULL, 'Fling_55', NULL, 'The user yells as if it''s ranting about something, which lowers the Sp. Atk stats of opposing Pokémon.'),
(509, 'TM79', 'TM79', 'TM79s', 4, 3000, 'TR', NULL, 'Fling_80', NULL, 'The user releases a horrible aura imbued with dark thoughts. This may also make the target flinch.'),
(510, 'TM80', 'TM80', 'TM80s', 4, 3000, 'TR', NULL, 'Fling_75', NULL, 'Large boulders are hurled at opposing Pokémon to inflict damage. This may also make them flinch.'),
(511, 'TM81', 'TM81', 'TM81s', 4, 3000, 'TR', NULL, 'Fling_80', NULL, 'The user slashes at the target by crossing its scythes or claws as if they were a pair of scissors.'),
(512, 'TM82', 'TM82', 'TM82s', 4, 1000, 'TR', NULL, 'Fling_10', NULL, 'While it is asleep, the user randomly uses one of the moves it knows.'),
(513, 'TM83', 'TM83', 'TM83s', 4, 3000, 'TR', NULL, 'Fling_60', NULL, 'The user strikes everything around it by stomping down on the ground. This lowers the Speed of those hit.'),
(514, 'TM84', 'TM84', 'TM84s', 4, 3000, 'TR', NULL, 'Fling_80', NULL, 'The target is stabbed with a tentacle, arm, or the like steeped in poison. This may also poison them.'),
(515, 'TM85', 'TM85', 'TM85s', 4, 3000, 'TR', NULL, 'Fling_100', NULL, 'The user eats the dreams of a sleeping target. The user''s HP is restored by half the damage dealt.'),
(516, 'TM86', 'TM86', 'TM86s', 4, 3000, 'TR', NULL, 'Fling_10', NULL, 'The user snares the target with grass and trips it. The heavier the target, the strong the move is.'),
(517, 'TM87', 'TM87', 'TM87s', 4, 1500, 'TR', NULL, 'Fling_10', NULL, 'The user enrages and confuses the target. However, this also sharply raises the target''s Attack stat.'),
(518, 'TM88', 'TM88', 'TM88s', 4, 3000, 'TR', NULL, 'Fling_60', NULL, 'The user pecks the target. If the target is holding a Berry, the user eats it and gains its effect.'),
(519, 'TM89', 'TM89', 'TM89s', 4, 3000, 'TR', NULL, 'Fling_70', NULL, 'After making its attack, the user rushes back to switch places with a party Pokémon in waiting.'),
(520, 'TM90', 'TM90', 'TM90s', 4, 2000, 'TR', NULL, 'Fling_10', NULL, 'The user creates a substitute for itself using some of its HP. The substitute serves as a decoy.'),
(521, 'TM91', 'TM91', 'TM91s', 4, 3000, 'TR', NULL, 'Fling_80', NULL, 'The user gathers all its light energy and releases it all at once. This may also lower the target''s Sp. Def stat.'),
(522, 'TM92', 'TM92', 'TM92s', 4, 5500, 'TR', NULL, 'Fling_10', NULL, 'The user creates a bizarre area in which slower Pokémon get to move first for five turns.'),
