(524, 'TM94', 'TM94', 'TM94s', 4, 2000, 'TR', NULL, 'Fling_90', NULL, 'The user flies up into the sky and then strikes its target on the next turn.'),
(525, 'TM95', 'TM95', 'TM95s', 4, 2500, 'TR', NULL, 'Fling_90', NULL, 'The user attacks everything around it by swamping its surroundings with a giant wave.'),
(526, 'TM96', 'TM96', 'TM96s', 4, 2000, 'TR', NULL, 'Fling_80', NULL, 'The target is slugged with a punch thrown at maximum power.'),
(527, 'TM97', 'TM97', 'TM97s', 4, 2000, 'TR', NULL, 'Fling_10', NULL, 'A strong wind blows away the target''s barriers, such as Reflect, and lowers their evasiveness.'),
(528, 'TM98', 'TM98', 'TM98s', 4, 2000, 'TR', NULL, 'Fling_40', NULL, 'The user attacks with a punch that may lower the target''s Defense stat.'),
(529, 'TM99', 'TM99', 'TM99s', 4, 2500, 'TR', NULL, 'Fling_80', NULL, 'The user charges at the target and may make it flinch.'),
(530, 'TM100', 'TM100', 'TM100s', 4, 2000, 'TR', NULL, 'Fling_90', NULL, 'A charging attack that may also leave the foe confused.'),
(531, 'HM01', 'HM01', 'HM01s', 4, 0, 'HM', NULL, NULL, NULL, 'The target is cut with a scythe or claw. This can also be used to cut down thin trees.'),
(532, 'HM02', 'HM02', 'HM02s', 4, 0, 'HM', NULL, NULL, NULL, 'The user soars and then strikes on the next turn. This can also be used to fly to any familiar town.'),
(533, 'HM03', 'HM03', 'HM03s', 4, 0, 'HM', NULL, NULL, NULL, 'Attacks everything by swamping the surroundings with a giant wave. This can also be used to cross water.'),
(534, 'HM04', 'HM04', 'HM04s', 4, 0, 'HM', NULL, NULL, NULL, 'The target is slugged with a punch thrown at maximum power. This can also be used to move heavy boulders.'),
(535, 'HM05', 'HM05', 'HM05s', 4, 0, 'HM', NULL, NULL, NULL, 'The user charges at the target and may make it flinch. It can also be used to climb a waterfall.'),
(536, 'HM06', 'HM06', 'HM06s', 4, 0, 'HM', NULL, NULL, NULL, 'Diving on the first turn, the user floats up and attacks on the second. It can be used to dive underwater.'),
