(641, 'DIREHIT', 'Dire Hit', 'Dire Hits', 7, 1000, NULL, 'OnBattler', 'Fling_30', NULL, 'An item that raises the critical-hit ratio greatly. It wears off if the Pokémon is withdrawn.'),
(642, 'DIREHIT2', 'Dire Hit 2', 'Dire Hit 2s', 7, 0, NULL, 'OnBattler', 'Fling_30', NULL, 'It sharply raises the critical-hit ratio. It wears off if the Pokémon is withdrawn.'),
(643, 'DIREHIT3', 'Dire Hit 3', 'Dire Hit 3s', 7, 0, NULL, 'OnBattler', 'Fling_30', NULL, 'It greatly raises the critical-hit ratio. It wears off if the Pokémon is withdrawn.'),
(644, 'GUARDSPEC', 'Guard Spec.', 'Guard Specs.', 7, 1500, NULL, 'Direct', 'Fling_30', NULL, 'An item that prevents stat reduction among the Trainer''s party Pokémon for five turns after use.'),
(645, 'RESETURGE', 'Reset Urge', 'Reset Urges', 7, 0, NULL, NULL, 'Fling_30', NULL, 'When used, it restores any stat changes of an ally Pokémon.'),
(646, 'ABILITYURGE', 'Ability Urge', 'Ability Urges', 7, 0, NULL, NULL, 'Fling_30', NULL, 'When used, it activates the Ability of an ally Pokémon.'),
(647, 'ITEMURGE', 'Item Urge', 'Item Urges', 7, 0, NULL, NULL, 'Fling_30', NULL, 'When used, it causes an ally Pokémon to use its held item.'),
(648, 'ITEMDROP', 'Item Drop', 'Item Drops', 7, 0, NULL, NULL, 'Fling_30', NULL, 'When used, it causes an ally Pokémon to drop a held item.'),
(649, 'BLUEFLUTE', 'Blue Flute', 'Blue Flutes', 7, 20, 'OnPokemon', 'OnPokemon', 'Fling_30', NULL, 'A blue flute made from blown glass. Its melody awakens a single Pokémon from sleep.'),
(650, 'YELLOWFLUTE', 'Yellow Flute', 'Yellow Flutes', 7, 20, NULL, 'OnBattler', 'Fling_30', NULL, 'A yellow flute made from blown glass. Its melody snaps a single Pokémon out of confusion.'),
(651, 'REDFLUTE', 'Red Flute', 'Red Flutes', 7, 20, NULL, 'OnBattler', 'Fling_30', NULL, 'A red flute made from blown glass. Its melody snaps a single Pokémon out of infatuation.'),
(652, 'POKEDOLL', 'Poké Doll', 'Poké Dolls', 7, 300, NULL, 'Direct', 'Fling_30', NULL, 'A doll that attracts Pokémon. Use it to flee from any battle with a wild Pokémon.'),
(653, 'FLUFFYTAIL', 'Fluffy Tail', 'Fluffy Tails', 7, 300, NULL, 'Direct', 'Fling_30', NULL, 'An item that attracts Pokémon. Use it to flee from any battle with a wild Pokémon.'),
(654, 'POKETOY', 'Poké Toy', 'Poké Toys', 7, 300, NULL, 'Direct', 'Fling_30', NULL, 'An item that attracts Pokémon. Use it to flee from any battle with a wild Pokémon.'),
(655, 'BICYCLE', 'Bicycle', 'Bicycles', 8, 0, 'Direct', NULL, 'KeyItem', NULL, 'A folding Bicycle that enables much faster movement than the Running Shoes.'),
(656, 'OLDROD', 'Old Rod', 'Old Rods', 8, 0, 'Direct', NULL, 'KeyItem', NULL, 'An old and beat-up fishing rod. Use it by any body of water to fish for wild aquatic Pokémon.'),
(657, 'GOODROD', 'Good Rod', 'Good Rods', 8, 0, 'Direct', NULL, 'KeyItem', NULL, 'A new, good-quality fishing rod. Use it by any body of water to fish for wild aquatic Pokémon.'),
(658, 'SUPERROD', 'Super Rod', 'Super Rods', 8, 0, 'Direct', NULL, 'KeyItem', NULL, 'An awesome, high-tech fishing rod. Use it by any body of water to fish for wild aquatic Pokémon.'),
(659, 'ITEMFINDER', 'Itemfinder', 'Itemfinders', 8, 0, 'Direct', NULL, 'KeyItem', NULL, 'A device used for finding items. If there is a hidden item nearby when it is used, it emits a signal.'),
(660, 'DOWSINGMACHINE', 'Dowsing Machine', 'Dowsing Machines', 8, 0, 'Direct', NULL, 'KeyItem', NULL, 'It checks for unseen items in the area and makes noise and lights when it finds something.'),
(661, 'POKERADAR', 'Poké Radar', 'Poké Radars', 8, 0, 'Direct', NULL, 'KeyItem', NULL, 'A tool that can search out Pokémon that are hiding in grass. Its battery is recharged as you walk.'),
(662, 'TOWNMAP', 'Town Map', 'Town Maps', 8, 0, 'Direct', NULL, 'KeyItem', NULL, 'A very convenient map that can be viewed anytime. It even shows your present location.'),
(663, 'ESCAPEROPE', 'Escape Rope', 'Escape Ropes', 8, 0, 'Direct', NULL, 'KeyItem', NULL, 'A long, durable rope. Use it to escape instantly from a cave or a dungeon.'),
(664, 'COINCASE', 'Coin Case', 'Coin Cases', 8, 0, 'Direct', NULL, 'KeyItem', NULL, 'A case for holding coins obtained at the Game Corner. It holds up to 99,999 coins.'),
(665, 'POKEFLUTE', 'Poké Flute', 'Poké Flutes', 8, 0, 'OnPokemon', 'Direct', 'KeyItem', NULL, 'A flute that is said to instantly awaken any Pokémon. It has a lovely tone.'),
(666, 'SOOTSACK', 'Soot Sack', 'Soot Sacks', 8, 0, NULL, NULL, 'KeyItem', NULL, 'A sack used to gather and hold volcanic ash.'),
(667, 'SILPHSCOPE', 'Silph Scope', 'Silph Scopes', 8, 0, NULL, NULL, 'KeyItem', NULL, 'A scope that makes unseeable Pokémon visible. It is made by Silph Co.'),
(668, 'DEVONSCOPE', 'Devon Scope', 'Devon Scopes', 8, 0, NULL, NULL, 'KeyItem', NULL, 'A device by Devon that signals any unseeable Pokémon.'),
(669, 'SQUIRTBOTTLE', 'Squirt Bottle', 'Squirt Bottles', 8, 0, NULL, NULL, 'KeyItem', NULL, 'A watering can shaped like a Squirtle. It helps promote healthy growth of Berries planted in soft soil.'),
(670, 'SPRAYDUCK', 'Sprayduck', 'Sprayducks', 8, 0, NULL, NULL, 'KeyItem', NULL, 'A watering can shaped like a Psyduck. It helps promote healthy growth of Berries planted in soft soil.'),
(671, 'WAILMERPAIL', 'Wailmer Pail', 'Wailmer Pails', 8, 0, NULL, NULL, 'KeyItem', NULL, 'A nifty watering pail. Use it to promote strong growth in Berries planted in soft soil.'),
(672, 'SPRINKLOTAD', 'Sprinklotad', 'Sprinklotads', 8, 0, NULL, NULL, 'KeyItem', NULL, 'A watering can shaped like a Lotad. It helps promote the healthy growth of any Berries planted in soft soil.'),
(673, 'GRACIDEA', 'Gracidea', 'Gracideas', 8, 0, 'OnPokemon', NULL, 'KeyItem', NULL, 'A flower sometimes bundled in bouquets to convey gratitude on special occasions like birthdays.'),
(674, 'REVEALGLASS', 'Reveal Glass', 'Reveal Glasses', 8, 0, 'OnPokemon', NULL, 'KeyItem', NULL, 'A glass that reveals the truth. It is a mysterious glass that returns a Pokémon back to its original shape.'),
(675, 'PRISONBOTTLE', 'Prison Bottle', 'Prison Bottles', 8, 0, 'OnPokemon', NULL, 'KeyItem', NULL, 'A bottle believed to have been used to seal away the power of a certain Pokémon long, long ago.'),
(676, 'ROTOMCATALOG', 'Rotom Catalog', 'Rotom Catalogs', 8, 0, 'OnPokemon', NULL, 'KeyItem', NULL, 'A catalog of devices that Rotom like. Use the catalog to have Rotom hop in and out of the devices listed within.'),
(677, 'ZYGARDECUBE', 'Zygarde Cube', 'Zygarde Cubes', 8, 0, 'OnPokemon', NULL, 'KeyItem', NULL, 'An item in which Zygarde Cores and Cells are gathered. You can also use it to change Zygarde''s forms.'),
(678, 'DNASPLICERS', 'DNA Splicers', 'DNA Splicers', 8, 0, 'OnPokemon', NULL, 'KeyItem', NULL, 'A splicer that fuses Kyurem and a certain Pokémon. They are said to have been one in the beginning.'),
(679, 'DNASPLICERSUSED', 'DNA Splicers', 'DNA Splicers', 8, 0, 'OnPokemon', NULL, 'KeyItem', NULL, 'A splicer that separates Kyurem and a certain Pokémon when they have been fused.'),
(680, 'NSOLARIZER', 'N-Solarizer', 'N-Solarizers', 8, 0, 'OnPokemon', NULL, 'KeyItem', NULL, 'A machine to fuse Necrozma, which needs light, and Solgaleo.'),
(681, 'NSOLARIZERUSED', 'N-Solarizer', 'N-Solarizers', 8, 0, 'OnPokemon', NULL, 'KeyItem', NULL, 'A machine to separate Necrozma, which needed light, from Solgaleo.'),
(682, 'NLUNARIZER', 'N-Lunarizer', 'N-Lunarizers', 8, 0, 'OnPokemon', NULL, 'KeyItem', NULL, 'A machine to fuse Necrozma, which needs light, and Lunala.'),
(683, 'NLUNARIZERUSED', 'N-Lunarizer', 'N-Lunarizers', 8, 0, 'OnPokemon', NULL, 'KeyItem', NULL, 'A machine to separate Necrozma, which needed light, from Lunala.'),
(684, 'REINSOFUNITY', 'Reins of Unity', 'Reins of Unity', 8, 0, 'OnPokemon', NULL, 'KeyItem', NULL, 'Reins that people presented to the king. They unite Calyrex with its beloved steed.'),
(685, 'REINSOFUNITYUSED', 'Reins of Unity', 'Reins of Unity', 8, 0, 'OnPokemon', NULL, 'KeyItem', NULL, 'Reins that people presented to the king. They separate Calyrex and its beloved steed.'),
(686, 'OVALCHARM', 'Oval Charm', 'Oval Charms', 8, 0, NULL, NULL, 'KeyItem', NULL, 'An oval charm said to increase the chance of Eggs being found at the Day Care.'),
(687, 'SHINYCHARM', 'Shiny Charm', 'Shiny Charms', 8, 0, NULL, NULL, 'KeyItem', NULL, 'A shiny charm said to increase the chance of finding a Shiny Pokémon.'),
(688, 'CATCHINGCHARM', 'Catching Charm', 'Catching Charms', 8, 0, NULL, NULL, 'KeyItem', NULL, 'A charm said to increase the chance of getting a critical catch. The charm doesn''t shake much.'),
(689, 'EXPCHARM', 'Exp. Charm', 'Exp. Charms', 8, 0, NULL, NULL, 'KeyItem', NULL, 'A charm that increases the Exp. Points that Pokémon can get. A machine-like object is inside it.'),
(690, 'MEGARING', 'Mega Ring', 'Mega Rings', 8, 0, NULL, NULL, 'KeyItem,MegaRing', NULL, 'This ring contains an untold power that somehow enables Pokémon carrying Mega Stones to Mega Evolve.'),
(691, 'POKEMONBOXLINK', 'Pokémon Box Link', 'Pokémon Box Links', 8, 0, NULL, NULL, 'KeyItem', NULL, 'A device that allows you to access the Pokémon storage system. There are some places where it won''t work.'),
